"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["59063"],{31792(e){e.exports=JSON.parse('{"id":"FIN-352","slug":"certificate-of-deposit","term":"Certificate of Deposit (CD)","also_known_as":["CD"],"difficulty":"Beginner","definition":"A certificate of deposit (CD) is a type of time deposit offered by banks and credit unions that pays a fixed interest rate for a fixed term, such as six months, one year or five years.","explanation":["A CD works much like other time deposits: you deposit a sum of money for a set period and earn a guaranteed rate of interest. The term is especially common in the United States.","CDs usually pay higher interest than regular savings accounts, with longer terms often paying higher rates. In exchange, the money is locked up until the CD matures. Withdrawing early typically means paying a penalty, often a few months\' worth of interest.","For example, a five-year CD of 5,000 paying 4% a year, compounded annually, would be worth about 6,083 at maturity.","Some investors use a strategy called laddering, splitting money across CDs that mature at different times, such as one, two, three, four and five years. As each CD matures, the money can be spent or reinvested, providing regular access to funds while still earning higher long-term rates.","CDs from insured banks are covered by deposit insurance up to the applicable limit. Some brokered CDs can be sold before maturity in a secondary market, but their price may be lower than the amount invested if interest rates have risen."],"note":"","total":1500,"prev":{"slug":"central-limit-theorem","term":"Central Limit Theorem"},"next":{"slug":"change-in-accounting-estimate","term":"Change in Accounting Estimate"}}')}}]);